{"command": "cd /workspace && cat > /tmp/cell.py <<'EOF'
import re,subprocess,sys
def cells(s,row):
    o=subprocess.run(["tmux","capture-pane","-t",s,"-p","-e"],capture_output=True,text=True).stdout.split("\n")
    if row>=len(o): return ''
    l=o[row]; r=[]; acs=False; bg=False; bold=False; i=0
    while i<len(l):
        m=re.match(r'\x1b\[([0-9;]*)m',l[i:])
        if m:
            for p in m.group(1).split(';'):
                p=p or '0'; n=int(p)
                if n in (0,49): bg=False
                elif n==1: bold=True
                elif n==22: bold=False
                elif 40<=n<=47: bg=True
            i+=m.end(); continue
        ch=l[i]
        if ch=='\x0e': acs=True; i+=1; continue
        if ch=='\x0f': acs=False; i+=1; continue
        r.append(ch if acs else ('B' if bg else ('*' if bold else ' ')))
        i+=1
    return r
if __name__=='__main__':
    s=sys.argv[1]
    for row in [int(x) for x in sys.argv[2].split(',')]:
        c=cells(s,row)
        # print runs
        runs=[];cur=None;st=0
        for j,v in enumerate(c):
            if v!=cur:
                if cur is not None and (cur!=' '): runs.append((st,j-1,cur))
                cur=v;st=j
        if cur is not None and cur!=' ': runs.append((st,len(c)-1,cur))
        print(row, [(a,b,t) for a,b,t in runs])
EOF
python3 /tmp/cell.py cx100d1 7,8,9,13,14; echo "--- cx110d1"; python3 /tmp/cell.py cx110d1 7,8,9,13,14"}

