def run(args, secs=1.3, cols=100, rows=20, term='xterm-256color', tz='UTC0'):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ['TERM']=term; os.environ['TZ']=tz
        fcntl.ioctl(0, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
