#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <locale.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <getopt.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curses.h>
#include <term.h>

/* ---------------------------------------------------------------- */
/* fonts                                                            */
/* ---------------------------------------------------------------- */

/* A glyph is five rows high.  Each of its cells covers two terminal
 * columns: digits are three cells (six columns) wide, the colon two
 * cells (four columns).  A single blank column separates glyphs. */
#define ROWS      5
#define D_CELLS   3
#define C_CELLS   2
#define CELL_W    2

static const unsigned char num[10][ROWS][D_CELLS] = {
