{"command": "cd /workspace && cat > /tmp/cmp2.py <<'EOF'
import re,subprocess,sys
def runs(sess,H=24,rows=None):
    o=subprocess.run(["tmux","capture-pane","-t",sess,"-p","-e"],capture_output=True,text=True).stdout.split("\n")
    out=[]
    for row in range(0,H):
        l=o[row]; acs=False;bg=False;bold=False;cells=[];ci=0
        while ci<len(l):
            m=re.match(r'\x1b\[([0-9;]*)m',l[ci:])
            if m:
                for p in m.group(1).split(';'):
                    p=p or '0';n=int(p)
                    if n in (0,49): bg=False
                    elif n==1: bold=True
                    elif n==22: bold=False
                    elif 40<=n<=47: bg=n-40
                ci+=m.end(); continue
            ch=l[ci]
            if ch=='\x0e': acs=True; ci+=1; continue
            if ch=='\x0f': acs=False; ci+=1; continue
            cells.append(('B',bg,bold) if bg else (('A',ch,bold) if acs else ('*',' ',bold))); ci+=1
        rs=[];cur=None;st=0
        for j,v in enumerate(cells):
            if v!=cur:
                if cur is not None and cur[0]!='*': rs.append((st,j-1,cur[0],cur[1],int(cur[2])))
                cur=v;st=j
        if cur is not None and cur[0]!='*': rs.append((st,len(cells)-1,cur[0],cur[1],int(cur[2])))
        out.append(rs)
    return out
a=runs(sys.argv[1],int(sys.argv[3])); b=runs(sys.argv[2],int(sys.argv[3]))
diff=0
for i,(x,y) in enumerate(zip(a,b)):
    if x!=y:
        diff+=1
        print("row %d:"%i); print("  orig:",x); print("  mine:",y)
