                if cur is not None and cur[0]!='*': rs.append((st,j-1,cur[0],cur[1],int(cur[2])))
                cur=v;st=j
        if cur is not None and cur[0]!='*': rs.append((st,len(cells)-1,cur[0],cur[1],int(cur[2])))
        out.append(rs)
    return out
